from fastapi import FastAPI

app = FastAPI()

@app.get("/")
def read_root():
    return {"Hello": "World"}

@app.get("/items/{item_id}")
def read_item(item_id: int, q: str = None):
    return {"item_id": item_id, "q": q}

@app.get("/items/{item_id}/comments/{comment_id}")
def read_comment(item_id: int, comment_id: int, q: str = None):
    return {"item_id": item_id, "comment_id": comment_id, "q": q}

@app.post("/items/{item_id}/comments")
def create_comment(item_id: int, comment: str, q: str = None):
    return {"item_id": item_id, "comment": comment, "q": q}

@app.put("/items/{item_id}/comments/{comment_id}")
def update_comment(item_id: int, comment_id: int, comment: str, q: str = None):
    return {"item_id": item_id, "comment_id": comment_id, "comment": comment, "q": q}

